  );
  if (!row) return res.status(404).end();
  res.json(row);
});
```

**`routes/accounts.js`, both handlers:**
```js
router.patch("/:id", async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 AND id = $4 RETURNING *",
    [req.body.display_name, req.body.billing_email, req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

router.delete("/:id", async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET deleted_at = now() WHERE id = $1 AND id = $2 RETURNING id",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.status(204).end();
});
```

**Why this shape:**
- **The check goes in the `UPDATE` itself, not in a separate `SELECT` first.** Checking and writing stay one atomic statement, so there's no gap between them. It also fits `db.write()`, which runs one statement per transaction.
- **`id = $3 AND id = $4` looks redundant, but it's on purpose.** It lets Postgres compare the two values. Comparing them in JS would put the string from the URL next to whatever pg returns for the column, which is a number if the column is `integer`. A strict `!==` would then reject every valid request. If you'd rather not take the account id from the URL at all, a `/accounts/me` route avoids the question.
